/**
 * CORS-Safe Embedded Gothic Fine Art & Procedural Library Textures
 * Ensures 100% WebGL texture rendering on both local file:// and https://garethenglish.com
 */
window.GOTHIC_PORTAL_DATA_URIS = {"baskerville":"data:image/jpeg;base64,","dracula":"data:image/jpeg;base64,","mural":"data:image/jpeg;base64,","frankenstein":"data:image/jpeg;base64,","alice":"data:image/jpeg;base64,","jekyll":"data:image/jpeg;base64,"}
;

window.GothicLibraryTextures = {
  createBookshelfTexture() {
    const c = document.createElement('canvas');
    c.width = 512;
    c.height = 512;
    const ctx = c.getContext('2d');

    // Deep mahogany backing
    ctx.fillStyle = '#180c07';
    ctx.fillRect(0, 0, 512, 512);

    const shelves = 6;
    const shelfH = 512 / shelves;
    const spineColors = ['#5c1616', '#133b2b', '#1b2845', '#4a2511', '#3b1832', '#2f2618', '#68211a', '#1d3828'];

    for (let s = 0; s < shelves; s++) {
      const yTop = s * shelfH;
      // Shelf shadow
      const grad = ctx.createLinearGradient(0, yTop, 0, yTop + shelfH);
      grad.addColorStop(0, '#090402');
      grad.addColorStop(0.2, '#1c0e08');
      grad.addColorStop(1, '#120804');
      ctx.fillStyle = grad;
      ctx.fillRect(8, yTop + 4, 496, shelfH - 12);

      // Draw books across the shelf
      let x = 14;
      while (x < 488) {
        const bw = 14 + Math.floor(Math.random() * 18);
        if (x + bw > 494) break;
        const bh = (shelfH - 18) * (0.78 + Math.random() * 0.2);
        const by = yTop + (shelfH - 10) - bh;
        const col = spineColors[(x + s * 7) % spineColors.length];

        ctx.fillStyle = col;
        ctx.fillRect(x, by, bw - 2, bh);

        // Spine highlight
        ctx.fillStyle = 'rgba(255,255,255,0.08)';
        ctx.fillRect(x + 2, by, 3, bh);

        // Gold leaf spine bands
        ctx.fillStyle = '#d99e47';
        ctx.fillRect(x + 2, by + 8, bw - 6, 2);
        ctx.fillRect(x + 2, by + bh - 10, bw - 6, 2);
        if (bh > 52) {
          ctx.fillRect(x + 3, by + Math.floor(bh * 0.45), bw - 8, 3);
        }
        x += bw;
      }

      // Wooden shelf plank
      ctx.fillStyle = '#3b1f12';
      ctx.fillRect(0, yTop + shelfH - 10, 512, 10);
      ctx.fillStyle = '#6b3b20';
      ctx.fillRect(0, yTop + shelfH - 10, 512, 2);
    }

    const tex = new THREE.CanvasTexture(c);
    tex.needsUpdate = true;
    return tex;
  },

  createCarpetTexture() {
    const c = document.createElement('canvas');
    c.width = 256;
    c.height = 512;
    const ctx = c.getContext('2d');

    ctx.fillStyle = '#471111';
    ctx.fillRect(0, 0, 256, 512);

    // Gold & navy Victorian runner border
    ctx.strokeStyle = '#d99e47';
    ctx.lineWidth = 8;
    ctx.strokeRect(18, 12, 220, 488);
    ctx.strokeStyle = '#1e293b';
    ctx.lineWidth = 4;
    ctx.strokeRect(30, 24, 196, 464);

    // Repeating medallions
    for (let y = 64; y < 460; y += 96) {
      ctx.fillStyle = 'rgba(217, 158, 71, 0.25)';
      ctx.beginPath();
      ctx.arc(128, y, 28, 0, Math.PI * 2);
      ctx.fill();
    }

    const tex = new THREE.CanvasTexture(c);
    tex.wrapS = THREE.RepeatWrapping;
    tex.wrapT = THREE.RepeatWrapping;
    tex.repeat.set(1, 5);
    tex.needsUpdate = true;
    return tex;
  },

  createPortalPaintingTexture(stationId, wingMeta) {
    const c = document.createElement('canvas');
    c.width = 512;
    c.height = 680;
    const ctx = c.getContext('2d');
    const tex = new THREE.CanvasTexture(c);

    const drawPlaqueAndFrame = () => {
      // Ornate Gold-Leaf Inner Bevel around Painting
      ctx.strokeStyle = '#d99e47';
      ctx.lineWidth = 10;
      ctx.strokeRect(12, 12, 488, 536);

      ctx.strokeStyle = '#78350f';
      ctx.lineWidth = 3;
      ctx.strokeRect(20, 20, 472, 520);

      // Museum Brass Nameplate Plaque at Bottom
      const plaqueGrad = ctx.createLinearGradient(0, 558, 0, 668);
      plaqueGrad.addColorStop(0, '#1c120c');
      plaqueGrad.addColorStop(1, '#0d0805');
      ctx.fillStyle = plaqueGrad;
      ctx.fillRect(12, 556, 488, 112);

      ctx.strokeStyle = wingMeta.hexStr || '#fbbf24';
      ctx.lineWidth = 3;
      ctx.strokeRect(16, 560, 480, 104);

      ctx.fillStyle = wingMeta.hexStr || '#fbbf24';
      ctx.font = 'bold 17px Georgia, serif';
      ctx.textAlign = 'center';
      ctx.fillText(wingMeta.eyebrow.toUpperCase(), 256, 590);

      ctx.fillStyle = '#ffffff';
      ctx.font = 'bold 24px Georgia, serif';
      ctx.fillText(wingMeta.shortTitle, 256, 622);

      ctx.fillStyle = '#cbbba2';
      ctx.font = 'italic 16px Georgia, serif';
      ctx.fillText(wingMeta.grammarTag, 256, 648);
    };

    // Immediate atmospheric oil base (so it is never white even before onload)
    const bgGrad = ctx.createRadialGradient(256, 270, 30, 256, 270, 300);
    bgGrad.addColorStop(0, wingMeta.hexStr || '#b45309');
    bgGrad.addColorStop(1, '#120a06');
    ctx.fillStyle = bgGrad;
    ctx.fillRect(16, 16, 480, 528);
    drawPlaqueAndFrame();
    tex.needsUpdate = true;

    // Load CORS-safe embedded base64 data URI
    const dataUri = window.GOTHIC_PORTAL_DATA_URIS && window.GOTHIC_PORTAL_DATA_URIS[stationId];
    if (dataUri) {
      const img = new Image();
      img.onload = () => {
        ctx.drawImage(img, 18, 18, 476, 524);
        // Subtle museum spotlight vignette
        const vig = ctx.createRadialGradient(256, 260, 110, 256, 270, 310);
        vig.addColorStop(0, 'rgba(255, 240, 200, 0.06)');
        vig.addColorStop(1, 'rgba(8, 5, 3, 0.42)');
        ctx.fillStyle = vig;
        ctx.fillRect(18, 18, 476, 524);
        drawPlaqueAndFrame();
        tex.needsUpdate = true;
      };
      img.src = dataUri;
    }

    return tex;
  }
};
